"""Diagnóstico del análisis general: cotización original, pips y referencia causal."""
import numpy as np

def build(ds,column,y,index,selection_size,test_size,ranking,test_metrics,test_prediction,methods,options,baseline_validation,fold_details):
    from engine import metrics
    name=ds.get('name','');ticker=name.upper();forex=ticker.endswith('=X') and column.lower() in ('open','high','low','close','adj close');pip=.01 if forex and 'JPY' in ticker else .0001 if forex else None
    last_train=float(y[selection_size-1]);truth=y[-test_size:];baseline=metrics(truth,np.full(len(truth),last_train));variance=float(np.var(truth));warnings=[];rows=[]
    for row in ranking:
        base=baseline_validation.get(row['method']);skill=1-row['mse']/base['mse'] if base and base['mse']>0 else None
        rows.append({'method':row['method'],'mse':row['mse'],'rmse':row['rmse'],'r2':row['r2'],'rmsePips':row['rmse']/pip if pip else None,'skillVsPersistence':skill,'persistenceMse':base['mse'] if base else None,'observations':row['observations']})
    if ranking and ranking[0]['observations']<50:warnings.append('La selección utiliza menos de 50 etiquetas VA. Compara más folds y bloques razonables; R² con poca variación local es inestable.')
    if any(r['mse']>0 and r['mse']<.0005 for r in ranking):warnings.append('MSE pequeño no equivale a error cero: ahora se muestra precisión ampliada/notación científica.')
    if rows and rows[0]['skillVsPersistence'] is not None and rows[0]['skillVsPersistence']<=0:warnings.append('El ganador no supera la persistencia en VA. No hay evidencia de mejora sobre mantener la última cotización en ese horizonte.')
    if fold_details and fold_details[0]['validationSamples']!=test_size:warnings.append(f"Horizontes distintos: cada VA externa tiene {fold_details[0]['validationSamples']} pasos y TE tiene {test_size}. Compara también con TE reservado del mismo horizonte que tu uso real; no confundas error de un paso con pronóstico de varios.")
    if forex:warnings.append('EURUSD/Forex: MSE está en cotización². El RMSE en pips facilita interpretar el error; el volumen de Yahoo para Forex suele no aportar señal.')
    advice=['Compara siempre con persistencia usando exactamente las mismas fechas y horizonte. Skill > 0 significa menor MSE que esa referencia.','En RNN/LSTM compara nivel, diferencia y log-retorno con los mismos folds; la salida se reconstruye a cotización antes de calcular MSE/R².','Empieza con 16–32 unidades, una capa, lote 32, LR 0.0003–0.001 y ES. Elige con VA, no por aproximar R² a 1.','Compara Standard y Robust sin ajustar escalas con VA/TE. Un scaler afín correcto no cambia R² de unas predicciones ya dadas.','TR/VA interna usan objetivos de un paso con contexto observado; VA externa y TE usan pronóstico recursivo. Una buena pérdida interna no garantiza varios pasos.']
    return {'kind':'series','dataset':name,'column':column,'metricUnits':'cotización² / cotización' if forex else 'unidad original² / unidad original','pipSize':pip,'folds':fold_details,'validation':rows,'holdout':{'samples':test_size,'firstDate':index[-test_size].isoformat(),'lastDate':index[-1].isoformat(),'trainLastDate':index[selection_size-1].isoformat()},'test':{'metrics':test_metrics,'persistence':baseline,'rmsePips':test_metrics['rmse']/pip if pip else None,'skillVsPersistence':1-test_metrics['mse']/baseline['mse'] if baseline['mse']>0 else None,'targetVariance':variance,'mseOverVariance':test_metrics['mse']/variance if variance>0 else None},'warnings':warnings,'recommendations':advice,'policy':'VA selecciona métodos. TE final no se usa para elegir parámetros. Los horizontes externos son recursivos. Componentes descriptivos (tendencia/estacionalidad/residuo) no son particiones TR/VA/TE.'}
